<script setup lang="ts">
import { reactive, ref } from "vue"; import AppShell from "@/components/zs/AppShell.vue"; import PageHeader from "@/components/zs/PageHeader.vue"; import Panel from "@/components/zs/Panel.vue"; import ScoreBadge from "@/components/crm/ScoreBadge.vue"; import ZButton from "@/components/zs/ZButton.vue"; import SidePanel from "@/components/zs/SidePanel.vue"; import Field from "@/components/zs/Field.vue"; import DataTable from "@/components/zs/DataTable.vue"; import ValidationMessage from "@/components/zs/ValidationMessage.vue"; import {useCrmData} from "@/composables/useCrmData"; import {useAsyncData,useMutation} from "@/composables/useAsyncData"; import {crmRepository} from "@/services/crm/repository"; import {showToast} from "@/composables/useToast"; import {setPageMeta} from "@/lib/page-meta";
setPageMeta("Lead Scoring","Configure deterministic CRM scoring rules.");const data=useCrmData(),open=ref(false);const rules=useAsyncData(()=>crmRepository.scoreRules(data.activeCompanyId.value),{watch:[data.activeCompanyId]});const form=reactive({name:"",target_type:"LEAD",field:"source",operator:"EQUALS",comparison_value:"",points:"10",position:"10",is_active:true});const mutation=useMutation(()=>crmRepository.createScoreRule(data.activeCompanyId.value,{...form,points:Number(form.points),position:Number(form.position)}));const recalc=useMutation((id:string)=>crmRepository.recalculateScore(data.activeCompanyId.value,"lead",id));async function save(){const saved=await mutation.run();if(!saved)return;open.value=false;await rules.refresh();showToast("Scoring rule saved",saved.name,"success");}async function calculate(id:string){const saved=await recalc.run(id);if(!saved)return;await data.leads.refresh();showToast("Score recalculated","The deterministic rules were applied.","success");}const columns=[{key:"name",header:"Rule"},{key:"field",header:"Field"},{key:"operator",header:"Operator"},{key:"comparisonValue",header:"Value"},{key:"points",header:"Points"},{key:"targetType",header:"Target"}];
</script>
<template><AppShell><PageHeader title="Lead Scoring" description="Deterministic, auditable fit and intent rules"><template #actions><ZButton @click="open=true">Add rule</ZButton></template></PageHeader><div class="grid gap-3 xl:grid-cols-[.8fr_1.2fr]"><Panel title="Scoring rules" description="Rules are evaluated by the backend"><DataTable :columns="columns" :rows="rules.data.value??[]" :min-width="650"/></Panel><Panel title="Lead scores" description="Recalculate from the active rules"><div class="divide-y divide-line px-4"><div v-for="lead in (data.leads.data.value??[]).slice(0,12)" :key="lead.id" class="flex items-center justify-between gap-4 py-3"><div><p class="text-sm font-medium text-content">{{lead.name}}</p><p class="text-xs text-content-muted">{{lead.company}} · {{lead.status}}</p></div><div class="flex items-center gap-2"><ScoreBadge :score="lead.score.total"/><ZButton variant="ghost" :disabled="recalc.saving.value" @click="calculate(lead.id)">Recalculate</ZButton></div></div></div></Panel></div><SidePanel :open="open" title="Add scoring rule" @close="open=false"><form class="grid gap-4 sm:grid-cols-2" @submit.prevent="save"><Field v-model="form.name" label="Rule name" required/><label><span class="label-caps">Target</span><select v-model="form.target_type" class="field mt-1.5"><option>LEAD</option><option>DEAL</option></select></label><label><span class="label-caps">Field</span><select v-model="form.field" class="field mt-1.5"><option v-for="value in ['source','email','phone','company_name','estimated_value','status','activity_count','days_inactive','amount','stage']" :key="value">{{value}}</option></select></label><label><span class="label-caps">Operator</span><select v-model="form.operator" class="field mt-1.5"><option>EQUALS</option><option>NOT_EMPTY</option><option>GREATER_OR_EQUAL</option><option>LESS_OR_EQUAL</option></select></label><Field v-model="form.comparison_value" label="Comparison value"/><Field v-model="form.points" label="Points" type="number" required/><Field v-model="form.position" label="Position" type="number" required/><ValidationMessage class="sm:col-span-2" :message="mutation.error.value?.message"/><ZButton type="submit" :disabled="mutation.saving.value">Save rule</ZButton></form></SidePanel></AppShell></template>
